import * as THREE from 'three'
import { useEffect, useRef, useState, useMemo } from 'react'
import { useFrame } from '@react-three/fiber'
import { useCursor, MeshReflectorMaterial, Image, Text, Environment, PerspectiveCamera } from '@react-three/drei'
import { easing } from 'maath'
import getUuid from 'uuid-by-string'
import { experiencesData } from './store'

const GOLDENRATIO = 1.61803398875

// Move imagePaths outside of the component
const imagePaths = [
  `${process.env.PUBLIC_URL}/Experiences/TUD.jpeg`,
  `${process.env.PUBLIC_URL}/Experiences/Entransys.jpeg`,
  `${process.env.PUBLIC_URL}/Experiences/Infosys.jpeg`,
  `${process.env.PUBLIC_URL}/Experiences/MercedesBenz.jpeg`,
  `${process.env.PUBLIC_URL}/Experiences/HHI.png`,
];

const useScreenSize = () => {
  const [size, setSize] = useState({ width: window.innerWidth, height: window.innerHeight })

  useEffect(() => {
    const handleResize = () => {
      setSize({ width: window.innerWidth, height: window.innerHeight })
    }
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  return size
}

const getImagePositions = (screenWidth, screenHeight) => {
  const aspectRatio = screenWidth / screenHeight
  const scale = Math.min(screenWidth, screenHeight) / 1200

  const basePositions = [
    { position: [0, 0, 1.5 * scale], rotation: [0, 0, 0] },
    { position: [-1.75 * aspectRatio * scale, 0, 0], rotation: [0, Math.PI / 2.5, 0] },
    { position: [-2 * aspectRatio * scale, 0, 0], rotation: [0, Math.PI / 2.5, 0] },
    { position: [1.75 * aspectRatio * scale, 0, 0], rotation: [0, -Math.PI / 2.5, 0] },
    { position: [2 * aspectRatio * scale, 0, 0], rotation: [0, -Math.PI / 2.5, 0] }
  ]

  if (screenWidth < 800) {
    basePositions[1].position[2] = 2 * scale
    basePositions[2].position[2] = 6 * scale
    basePositions[3].position[2] = 2 * scale
    basePositions[4].position[2] = 6 * scale
  } else if (screenWidth < 1700) {
    basePositions[1].position[2] = 1 * scale
    basePositions[2].position[2] = 4 * scale
    basePositions[3].position[2] = 1 * scale
    basePositions[4].position[2] = 4 * scale
  } else {
    basePositions[1].position[2] = 0.8 * scale
    basePositions[2].position[2] = 2 * scale
    basePositions[3].position[2] = 0.8 * scale
    basePositions[4].position[2] = 2 * scale
  }

  return basePositions.map((pos, index) => ({ ...pos, url: imagePaths[index] }))
}

export const Experiences = () => {
  const { width, height } = useScreenSize()
  const images = useMemo(() => getImagePositions(width, height), [width, height])

  return (
    <>
      <Lights preset="city" />
      <PerspectiveCamera makeDefault position={[0, 2, 10]} fov={70} />
      <fog attach="fog" args={['#191920', 0, 15]} />
      <group position={[0, -0.5, 0]}>
        <Frames images={images} />
        <mesh rotation={[-Math.PI / 2, 0, 0]}>
          <planeGeometry args={[25, 25]} />
          <MeshReflectorMaterial
            blur={[300, 100]}
            resolution={2048}
            mixBlur={1}
            mixStrength={80}
            roughness={1}
            depthScale={1.2}
            minDepthThreshold={0.4}
            maxDepthThreshold={1.4}
            color="#050505"
            metalness={0.8}
          />
        </mesh>
      </group>
    </>
  )
}

function Frames({ images }) {
  const ref = useRef()
  const [activeFrame, setActiveFrame] = useState(null)
  const [targetPosition, setTargetPosition] = useState(new THREE.Vector3(0, 0, 5.5))
  const [targetQuaternion, setTargetQuaternion] = useState(new THREE.Quaternion())

  useEffect(() => {
    if (activeFrame) {
      const clickedObject = ref.current.getObjectByName(activeFrame)
      if (clickedObject) {
        clickedObject.parent.updateWorldMatrix(true, true)
        const newPosition = new THREE.Vector3(0, GOLDENRATIO / 2, 1.6)
        clickedObject.parent.localToWorld(newPosition)
        const newQuaternion = new THREE.Quaternion()
        clickedObject.parent.getWorldQuaternion(newQuaternion)
        setTargetPosition(newPosition)
        setTargetQuaternion(newQuaternion)
        
        // Update experiencesData with the selected frame's filename without extension
        const selectedImage = images.find(img => getUuid(img.url) === activeFrame)
        if (selectedImage) {
          const filename = selectedImage.url.split('/').pop().split('.')[0]
          experiencesData.activeExperience = filename
        }
      }
    } else {
      setTargetPosition(new THREE.Vector3(0, 0, 5.5))
      setTargetQuaternion(new THREE.Quaternion())
      
      // Clear the selectedFrameUrl when no frame is selected
      experiencesData.activeExperience = null
    }
  }, [activeFrame, images])

  useFrame((state, dt) => {
    easing.damp3(state.camera.position, targetPosition, 0.4, dt)
    easing.dampQ(state.camera.quaternion, targetQuaternion, 0.4, dt)
  })

  function onClickFrame(e) {
    e.stopPropagation()
    const clickedName = e.object.name
    setActiveFrame(prevActive => prevActive === clickedName ? null : clickedName)
  }

  return (
    <group
      ref={ref}
      onClick={onClickFrame}
      onPointerMissed={() => setActiveFrame(null)}>
      {images.map((props) => (
        <Frame 
          key={props.url} 
          {...props} 
          active={activeFrame === getUuid(props.url)}
          isAnyActive={activeFrame !== null}
        />
      ))}
    </group>
  )
}

function Frame({ url, active, isAnyActive, ...props }) 
{
  const image = useRef()
  const frame = useRef()
  const [hovered, hover] = useState(false)
  const name = getUuid(url)
  useCursor(hovered)

  if (isAnyActive && !active) {
    return null
  }

  return (
    <group {...props}>
      <mesh
        name={name}
        onPointerOver={(e) => (e.stopPropagation(), hover(true))}
        onPointerOut={() => { hover(false) }}
        scale={[1, GOLDENRATIO, 0.05]}
        position={[0, GOLDENRATIO / 2, 0]}>
        <boxGeometry />
        <meshStandardMaterial color="#151515" metalness={0.5} roughness={0.5} envMapIntensity={2} />
        <mesh ref={frame} raycast={() => null} scale={[0.9, 0.93, 0.9]} position={[0, 0, 0]}>
          <boxGeometry />
          <meshBasicMaterial toneMapped={false} fog={false} />
        </mesh>
        <Image raycast={() => null} ref={image} position={[0, 0, 0.6]} scale={[0.9, 0.94, 1]} url={url} zoom={0.6} />
      </mesh>
      {!active && (
        <Text maxWidth={0.1} anchorX="left" anchorY="top" position={[0.55, GOLDENRATIO, 0]} fontSize={0.025}>
          {name.split('-').join(' ')}
        </Text>
      )}
    </group>
  )
}

function Lights({ preset }) {
  return (
    <>
      <ambientLight intensity={1} />
      <pointLight position={[20, 30, 10]} />
      <pointLight position={[-10, -10, -10]} color="blue" />
      <Environment preset={preset} />
    </>
  )
}